import dataclasses
import re

@dataclasses.dataclass(frozen=True)
class Token:
    kind: str
    text: str
    value: object
    offset: int

def tokenize(src: str) -> list[Token]:
 tokens = []
  pos = 0
  while pos < len(src):
    c = src[pos]
    if c.isspace():
      pos += 1
      continue
    if c == '/':
      if pos + 1 < len(src) and src[pos + 1] == '/':
        pos = src.find('\n', pos + 2)
         if pos == -1:
            pos = len(src)
         continue
      else:
         raise LexError(pos)
    if c.isdigit():
      match = re.match(r'\d+', src[pos:])
      if match:
        text = match.group 0
        value = int(text)
        tokens.append(Token("INT", text, value, pos))
        pos += len(text)
        continue
      match = re.match(r'\d+\.\d*', src[pos:])
      if match:
        text = match.group(0)
        value = float(text)
 tokens.append(Token("FLOAT", text, value, pos))
        pos += len(text)
        continue
      raise LexError(pos)
    if c == '.':
      raise LexError(pos)
    if c == '"':
      start = pos
      pos += 1
      text = ""
      while pos < len(src):
        if src[pos] == '"':
          pos += 1
          break
        if src[pos] == '\\':
          pos += 1
          if pos >= len(src):
            raise LexError(start)
          if src[pos] == 'n':
            text += '\n'
          elif src[pos] == 't':
            text += '\t'
          elif src[pos] == '"':
            text += '"'
          elif src[pos] == '\\':
            text += '\\'
          else:
            raise LexError(start)
        else:
          text += src[pos]
        pos += 1
      else:
        raise LexError(start)
      tokens.append(Token("STRING", text, text, start))
      continue
    if c.isalpha() or c == '_':
      match = re.match(r'[A-Za-z_][A-Za-z0-9_]*', src[pos:])
      if match:
        text = match.group(0)
         if text in ("let", "print", "if", "else", "while", "true", "false", "and", "or", "not"):
            tokens.append(Token("KEYWORD", text, text, pos))
         else:
            tokens.append(Token("IDENT ", text, text, pos))
         pos += len(text)
         continue
      raise LexError(pos)
    raise LexError(pos)
  return tokens
