from microvm.compiler import Program, Instr

def disassemble(program):
    lines = []
    for index, instr in enumerate(program.instructions):
        if instr.arg is None:
            lines.append(f"{index:04d} {instr.op}")
        else:
            text = f"{index:04d} {instr.op} {instr.arg}"
            if instr.op == "CONST":
                rendered = _render_constant(program.constants [instr.arg])
                lines.append(f"{text}  ; {rendered}")
            else:
                lines.append(text)
    return "\n".join(lines) + "\n"

def _render_constant(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value )
