from microvm.parser import ProgramNode, Block, LetStmt, IfStmt, WhileStmt, AssignStmt, PrintStmt , BinaryOp, UnaryOp, IntLit, FloatLit, StringLit, BoolLit, Ident
from microvm.errors import VMRuntimeError

_NO_FOLD = object()

def fold_constants(node):
    if isinstance(node, ProgramNode):
        return ProgramNode([fold_constants(s) for s in node.stat ements])
    if isinstance(node, Block):
        return Block([fold_constants(s) for s in node.statements], node.offset)
    if isinstance(node, LetStmt):
        return LetStmt(node.name, fold_constants(node.expr), node.offset)
    if isinstance(node, IfStmt):
        return IfStmt(fold _constants(node.cond), fold_constants(node.body), fold_constants(node.else_body), node.offset)
    if isinstance(node, WhileStmt):
        return WhileStmt(fold_constants(node.cond), fold_constants(node.body), node.offset)
    if isinstance(node, AssignStmt):
        return AssignStmt(node.name, fold_constants(node.expr ), node.offset)
    if isinstance(node, PrintStmt):
        return PrintStmt(fold_constants(node.expr), node.offset)
    if isinstance(node, BinaryOp):
        return _fold_binary(node)
    if isinstance(node, UnaryOp):
        return _fold_unary(node)
    return node

def _fold_binary (node):
    left = fold_constants(node.left)
    right = fold_constants(node.right)
    if node.op == "and":
        return _fold_and(left, right, node.offset)
    if node.op == "or":
        return _fold_or(left, right, node.offset)
