        if folded is not _NO_FOLD:
            return _make_lit(folded, node.offset)
    return BinaryOp(node.op, left, right, node.offset)

def _fold_and(left, right, offset):
    if isinstance(left, BoolLit) and isinstance(right, BoolLit):
        return BoolLit(left.value and right.value, offset)
    if isinstance(left, BoolLit) and not left.value:
        return BoolLit(False, offset)
    return BinaryOp("and", left, right, offset)

def _fold_or(left, right, offset):
    if isinstance(left, BoolLit) and isinstance(right, BoolLit):
        return BoolLit(left.value or right.value, offset)
    if isinstance (left, BoolLit) and left.value:
        return BoolLit(True, offset)
    return BinaryOp("or", left, right, offset)

def _fold_unary(node):
    operand = fold_constants(node.operand)
    if isinstance(operand, (IntLit, FloatLit, StringLit, Bool Lit)):
        folded = _try_fold_op(node.op, operand.value)
        if folded is not _NO_FOLD:
            return _make_lit(folded, node.offset)
    return UnaryOp(node.op, operand, node.offset)

def _try_fold_op(op, left, right):
    try:
        from microvm.vm import eval_binary
        return eval_binary(op, left, right)
    except VMRuntimeError:
        return _NO_FOLD

def _make_lit(value, offset):
    if isinstance(value, bool):
        return BoolLit(value, offset)
    if isinstance(value, int):
        return Int Lit(value, offset)
    if isinstance(value, float):
        return FloatLit(value, offset)
    if isinstance(value, str):
        return StringLit(value, offset)
    return _NO_FOLD
